#!/usr/bin/env node
// AIFIRST: generator for transitions_gen.go (CR-2026-002 TASK-04).
//
// Reads the tools package's dir-graph.yaml#change-request-track.state_machine and
// emits a read-only Go copy used by governance/crsync.go to validate transition
// legality before projecting (SDD §4.4).
//
// The generated file is COMMITTED (header records the source tools commit SHA).
// The --check mode regenerates and diffs against the committed file, exiting
// non-zero on drift — CI/pre-commit use it to guard consistency, so building
// multica never requires a tools checkout (SDD-SUG-003).
//
// Usage (from the multica repo root):
//   node server/internal/governance/gen/generate-transitions.mjs [--tools <path>] [--check]
// Default tools path: ../tools (sibling directory convention).

import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.resolve(__dirname, '..', 'transitions_gen.go');

const args = process.argv.slice(2);
const check = args.includes('--check');
const toolsIdx = args.indexOf('--tools');
const toolsDir = toolsIdx >= 0 ? path.resolve(args[toolsIdx + 1]) : path.resolve(__dirname, '..', '..', '..', '..', '..', 'tools');

const yamlPath = path.join(toolsDir, 'dir-graph.yaml');
// Normalize line endings first: a CRLF checkout (Windows autocrlf) makes the
// multi-line regexes below fail silently — this exact pitfall already bit twice
// during M0 and TASK-03.
const text = fs.readFileSync(yamlPath, 'utf8').replaceAll('\r\n', '\n');

// Line-level parsing of the state_machine block only: transitions, wildcards,
// terminal. Zero dependencies by design.
const transRe = /-\s*\{\s*from:\s*"?([^,"]+)"?\s*,\s*to:\s*([a-z-]+)\s*,\s*trigger:\s*"([^"]+)"\s*\}/g;
const raw = [];
for (const m of text.matchAll(transRe)) raw.push({ from: m[1].trim(), to: m[2].trim(), trigger: m[3].trim() });
if (raw.length === 0) { console.error('no transitions parsed — has the dir-graph.yaml structure changed?'); process.exit(2); }

const wcMatch = text.match(/wildcards:\s*\n\s+any-active:\s*\n((?:\s+-\s+[a-z-]+\n)+)/);
const anyActive = wcMatch ? [...wcMatch[1].matchAll(/-\s+([a-z-]+)/g)].map((m) => m[1]) : [];
const termMatch = text.match(/terminal:\s*\[([^\]]+)\]/);
const terminal = termMatch ? termMatch[1].split(',').map((s) => s.trim()) : [];
if (anyActive.length === 0 || terminal.length === 0) {
  console.error('wildcards/terminal not parsed — has the dir-graph.yaml structure changed?');
  process.exit(2);
}

// Expand wildcards; (new) becomes "" (no status exists before registration).
const expanded = [];
for (const t of raw) {
  const from = t.from === '(new)' ? '' : t.from;
  if (from === 'any-active') {
    for (const s of anyActive) expanded.push({ from: s, to: t.to, trigger: t.trigger });
  } else {
    expanded.push({ from, to: t.to, trigger: t.trigger });
  }
}

const shaR = spawnSync('git', ['-C', toolsDir, 'rev-parse', 'HEAD'], { encoding: 'utf8', shell: false });
const toolsSha = shaR.status === 0 ? shaR.stdout.trim() : 'unknown';

const statuses = [...new Set(expanded.flatMap((t) => [t.from, t.to]).filter(Boolean))].sort();

const lines = [];
lines.push('// Code generated by gen/generate-transitions.mjs from tools dir-graph.yaml. DO NOT EDIT.');
lines.push('//');
lines.push('// AIFIRST: read-only copy of the CR state machine (CR-2026-002 TASK-04).');
lines.push(`// Source: tools@${toolsSha} dir-graph.yaml#change-request-track.state_machine`);
lines.push(`// ${raw.length} declared transitions (incl. wildcards), ${expanded.length} after expansion.`);
lines.push('// Consistency is guarded by the gen script --check mode: regenerate != this file -> non-zero exit.');
lines.push('package governance');
lines.push('');
lines.push('// Transition is one legal state-machine transition. An empty From means pre-registration ((new)).');
lines.push('type Transition struct {');
lines.push('\tFrom    string');
lines.push('\tTo      string');
lines.push('\tTrigger string');
lines.push('}');
lines.push('');
lines.push('// Transitions follows the dir-graph.yaml declaration order (wildcards expanded).');
lines.push('var Transitions = []Transition{');
for (const t of expanded) lines.push(`\t{From: ${JSON.stringify(t.from)}, To: ${JSON.stringify(t.to)}, Trigger: ${JSON.stringify(t.trigger)}},`);
lines.push('}');
lines.push('');
lines.push('// TerminalStatuses is the set of terminal states: no transitions are accepted once entered.');
lines.push(`var TerminalStatuses = map[string]bool{${terminal.map((s) => `${JSON.stringify(s)}: true`).join(', ')}}`);
lines.push('');
lines.push('// KnownStatuses enumerates every named status (the (new) empty string is excluded).');
lines.push('var KnownStatuses = map[string]bool{');
// gofmt aligns map values in a column; emit the same alignment so the generated file is gofmt-clean
const maxKey = Math.max(...statuses.map((s) => JSON.stringify(s).length));
for (const s of statuses) {
  const key = JSON.stringify(s);
  lines.push(`\t${key}:${' '.repeat(maxKey - key.length + 1)}true,`);
}
lines.push('}');
lines.push('');
lines.push('// IsLegalTransition reports whether (from -> to) is a declared legal transition.');
lines.push('// An empty trigger matches on (from, to) only (the commit-scan fallback channel');
lines.push('// cannot recover the trigger).');
lines.push('func IsLegalTransition(from, to, trigger string) bool {');
lines.push('\tfor _, t := range Transitions {');
lines.push('\t\tif t.From != from || t.To != to {');
lines.push('\t\t\tcontinue');
lines.push('\t\t}');
lines.push('\t\tif trigger == "" || t.Trigger == trigger {');
lines.push('\t\t\treturn true');
lines.push('\t\t}');
lines.push('\t}');
lines.push('\treturn false');
lines.push('}');
lines.push('');

const out = lines.join('\n');

if (check) {
  const existing = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  // Ignore the source-SHA line when diffing (tools commits advance without the
  // state machine changing; that must not count as drift).
  const strip = (s) => s.replaceAll('\r\n', '\n').split('\n').filter((l) => !l.startsWith('// Source: tools@')).join('\n');
  if (strip(existing) !== strip(out)) {
    console.error('transitions_gen.go differs from a fresh regeneration off tools dir-graph.yaml — state machine drift; regenerate and commit.');
    process.exit(1);
  }
  console.log(`transitions consistency OK: ${expanded.length} transitions (tools@${toolsSha.slice(0, 7)})`);
} else {
  fs.writeFileSync(OUT, out, 'utf8');
  console.log(`generated ${OUT}: ${expanded.length} transitions (source tools@${toolsSha.slice(0, 7)})`);
}
